INSERT INTO `venues` VALUES (1,13,5,'서대문구 쿠킹 파티룸 82345','대관 목적에 맞게 이용하는 서대문구 쿠킹 파티룸 82345 공간입니다.','최대 12명. 생성 이미지이며 실제 공간과 다를 수 있습니다.',12,30000,3,9,23,'spacecloud','82345',1,'2026-11-05 10:28:10'),
